export default {"style.css":":root{color-scheme:light;--ink:#17251e;--muted:#4e6054;--paper:#fbf9f2;--surface:#f3f1e8;--line:#d6d9ca;--forest:#234b38;--accent:#dce8d6;--gold:#eddfb7;--serif:\"Instrument Serif\",Georgia,serif;--sans:\"Instrument Sans\",system-ui,sans-serif}\n*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.62 var(--sans)}\na{color:#254b38;text-underline-offset:4px}a:hover{color:#102b1d}a:focus-visible,button:focus-visible,select:focus-visible,input:focus-visible{outline:2px solid #296a49;outline-offset:3px}\n.wrap{width:min(1100px,calc(100% - 42px));margin-inline:auto}.top{border-bottom:1px solid var(--line)}.top-inner{min-height:69px;display:flex;align-items:center;justify-content:space-between;gap:18px;flex-wrap:wrap;padding:10px 0}\n.brand{font-weight:780;letter-spacing:.1em;font-size:.82rem;text-decoration:none}.top nav{display:flex;gap:13px 20px;flex-wrap:wrap}.top nav a{font-size:.9rem;text-decoration:none}\n.skip{position:absolute;left:-999px}.skip:focus{left:12px;top:12px;background:white;padding:10px;z-index:3}\n.hero{min-height:450px;display:grid;grid-template-columns:1.45fr 1fr;gap:clamp(22px,7vw,85px);align-items:center;padding:clamp(28px,6vw,72px) 0}.hero-copy{max-width:55ch;color:#3d5144;font-size:1.13rem}\nh1,h2,h3{font-family:var(--serif);font-weight:normal;line-height:1.1;margin:0}h1{font-size:clamp(3.1rem,9.2vw,7.7rem);letter-spacing:-.068em;margin-top:.18em}h2{font-size:clamp(2rem,4.3vw,3.85rem);letter-spacing:-.045em}h3{font-size:1.47rem;letter-spacing:-.018em}\n.byline,.eyebrow,.key,.record-date{font-family:\"IBM Plex Mono\",ui-monospace,monospace}.byline,.eyebrow{font-weight:700;font-size:.77rem;letter-spacing:.14em;color:var(--muted);margin:0 0 8px}\n.actions,.controls{display:flex;flex-wrap:wrap;gap:11px;align-items:center}.actions{margin-top:25px;gap:19px}\nbutton,.primary{font:650 .92rem/1.3 var(--sans);border:1px solid #b6c2b5;border-radius:7px;padding:9px 13px;background:var(--paper);color:var(--ink);cursor:pointer;text-decoration:none;display:inline-block}\nbutton:disabled{opacity:.6;cursor:default}button:hover:not(:disabled){background:var(--accent)}.primary{background:var(--forest);color:#fffdf4;border-color:var(--forest)}\n.primary:hover:not(:disabled){background:#173a29;color:white}.hero-count{padding:26px;border-radius:13px;background:#244735;color:#fff9e9;display:grid;grid-template-columns:1fr 1fr;gap:15px}\n.hero-count strong{font:normal clamp(2.9rem,7vw,6rem)/1 var(--serif)}.hero-count div p{font-size:.82rem;margin:5px 0}.hero-count>p{border-top:1px solid #66836e;margin:4px 0 0;padding-top:11px;grid-column:1/-1;font-size:.82rem;color:#e9eddf}\n.section{border-top:1px solid var(--line);padding:36px 0 55px;scroll-margin-top:12px}.section-head{display:grid;grid-template-columns:1.35fr 1fr;gap:22px;align-items:end;margin-bottom:20px}.section-head>p{margin:0;color:var(--muted);max-width:51ch}\n.panel,.cards article{border:1px solid var(--line);background:var(--surface);border-radius:11px;padding:clamp(15px,3vw,25px)}.panel+.panel{margin-top:14px}.cards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin:16px 0}\n.cards p{margin:9px 0 0}.cards .sources{margin-top:14px}.sources,.micro{font-size:.88rem;color:var(--muted)}.controls label{font-size:.84rem;font-weight:650;display:flex;flex-wrap:wrap;gap:8px;align-items:center}\ninput,select{font:inherit;color:var(--ink);background:var(--paper);border:1px solid #b6c2b5;border-radius:6px;padding:7px;min-width:0}input[type=range]{accent-color:var(--forest);cursor:pointer;padding:0;min-height:26px}\ninput[type=number]{width:105px;font-variant-numeric:tabular-nums}.jump-years{display:flex;gap:6px;flex-wrap:wrap}.jump-years button{padding:6px 10px}.range-label{display:block;margin-top:16px;color:var(--muted);font-size:.86rem}#window{width:100%;margin:4px 0 11px}\n.lanes{display:grid;grid-template-columns:1fr 1fr;gap:14px}.lane{background:#fffdf7;border:1px solid var(--line);padding:13px;border-radius:8px}.lane-label{display:flex;gap:8px;flex-wrap:wrap;justify-content:space-between;margin-bottom:10px}.lane-label span,.lane p{color:var(--muted);font-size:.86rem}.lane p{margin:10px 0 0}.ticks{display:flex;gap:3px}.tick{flex:1;height:16px;border-radius:2px;background:#dbe2d6}.tick:first-child{border:1px solid #527058}.tick.at-phase{background:#316247}\n.result{padding:9px 11px;background:var(--accent);border-radius:6px;font-weight:670}.table-wrap{overflow-x:auto;margin:12px 0}\ntable{width:100%;border-collapse:collapse}td,th{text-align:left;padding:9px 10px;border-bottom:1px solid var(--line)}th[scope=row]{font-weight:550;min-width:175px}\ntd:last-child{white-space:nowrap}.play-phrase{font-size:.78rem;padding:6px 9px}.current-phrase{background:#deead6}\nblockquote{margin:11px 0;padding:4px 0 4px 14px;border-left:3px solid var(--forest);color:var(--muted)}.motion-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(42px,1fr));gap:5px;list-style:none;padding:0;margin:12px 0 16px}.motion-grid li{text-align:center;border-radius:5px;padding:3px 1px;background:var(--gold);line-height:1.35}\n.motion-grid li.vertical{background:#d8e7d8}.motion-grid li.active-motion{outline:2px solid var(--forest);outline-offset:1px}.motion-grid span{font-size:1.25rem;display:block}.motion-grid small{font-size:.7rem}\n.rhythm-register summary{cursor:pointer;font-weight:700}.rhythm-register ol{columns:2;list-style:none;padding:0;margin:12px 0}.rhythm-register li{padding:4px 0;break-inside:avoid}.key{font-size:.8rem;color:var(--muted)}\n.scale-panel{margin-bottom:22px}.pillars li{list-style:none;margin:5px 0}.pillars ul{padding:0}.timeline-controls{margin:15px 0}.timeline{list-style:none;margin:0;padding:0}\n.timeline>li{display:grid;grid-template-columns:minmax(120px,175px) 1fr;gap:16px;padding:16px 0;border-top:1px solid var(--line)}.timeline li[hidden]{display:none}.timeline p{margin:7px 0 0}.record-date{font-size:.86rem;color:var(--forest)}.record-date span{display:block;color:var(--muted);font: .82rem var(--sans);margin-top:5px}\nfooter{background:var(--surface);border-top:1px solid var(--line);padding:20px 0;font-size:.88rem}\n@media(max-width:680px){.wrap{width:calc(100% - 28px)}.hero,.section-head{grid-template-columns:1fr;gap:18px}.hero{min-height:auto}.hero-count{max-width:430px}.lanes,.cards{grid-template-columns:1fr}.timeline>li{grid-template-columns:1fr;gap:4px}.record-date span{display:inline;margin-left:9px}.rhythm-register ol{columns:1}.top nav{gap:7px 11px}.top nav a{font-size:.82rem}}\n@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}\n","app.mjs":"import { cycleAt, heartbeat, minYear, maxYear, scaleValue, score } from \"./model.mjs\";\n\nconst byId = id => document.getElementById(id);\n\nconst year = byId(\"year\");\nconst windowYear = byId(\"window\");\nconst yearResult = byId(\"shared-status\");\nconst earlier = byId(\"earlier\");\nconst later = byId(\"later\");\n\nfunction showYear() {\n  try {\n    if (!year.value.trim()) throw new RangeError(\"Enter a year.\");\n    const state = cycleAt(Number(year.value));\n    windowYear.value = state.year;\n    earlier.disabled = state.year <= minYear;\n    later.disabled = state.year >= maxYear;\n    state.broods.forEach(b => {\n      const lane = document.querySelector('[data-period=\"' + b.cycleYears + '\"]');\n      [...lane.children].forEach((tick, i) => tick.classList.toggle(\"at-phase\", i === b.phase));\n      byId(\"phase-\" + b.cycleYears).textContent =\n        \"Phase \" + b.phase + \" of \" + b.cycleYears + (b.scheduled ? \" · scheduled this year\" : \"\") +\n        \" · next emergence \" + b.nextYear;\n    });\n    const current = state.shared ? \"both broods scheduled\" : \"most recent shared year \" + state.sharedAtOrBefore;\n    yearResult.textContent = state.year + \" · \" + current + \". Next shared year: \" + state.nextSharedYear + \".\";\n  } catch (error) {\n    yearResult.textContent = error.message;\n  }\n}\n\nconst setYear = value => {\n  year.value = value;\n  showYear();\n};\nyear.addEventListener(\"input\", showYear);\nwindowYear.addEventListener(\"input\", () => setYear(windowYear.value));\nearlier.addEventListener(\"click\", () => setYear(Math.max(minYear, Number(year.value || 2024) - 1)));\nlater.addEventListener(\"click\", () => setYear(Math.min(maxYear, Number(year.value || 2024) + 1)));\nfor (const button of document.querySelectorAll(\"[data-year]\")) {\n  button.addEventListener(\"click\", () => setYear(button.dataset.year));\n}\n\nconst tempo = byId(\"tempo\");\nconst play = byId(\"play-score\");\nconst stop = byId(\"stop-score\");\nconst audioStatus = byId(\"audio-status\");\nconst rows = [...document.querySelectorAll(\"[data-phrase-row]\")];\nconst midi = { \"F♯\": 66, \"G♯\": 68, \"A♯\": 70, \"C♯\": 73, \"D♯\": 75 };\nlet audio;\nlet playback;\n\nfunction stopAudio(message) {\n  if (!playback) return;\n  for (const timer of playback.timers) clearTimeout(timer);\n  for (const voice of playback.voices) voice.stop();\n  playback.bus?.disconnect();\n  playback = null;\n  rows.forEach(row => row.classList.remove(\"current-phrase\"));\n  stop.disabled = true;\n  audioStatus.textContent = message;\n}\n\nfunction pulse(note, start, length, bus) {\n  const oscillator = audio.createOscillator();\n  const envelope = audio.createGain();\n  oscillator.type = \"triangle\";\n  oscillator.frequency.value = 440 * 2 ** ((midi[note] - 69) / 12);\n  envelope.gain.setValueAtTime(0.0001, start);\n  envelope.gain.exponentialRampToValueAtTime(0.075, start + 0.016);\n  envelope.gain.exponentialRampToValueAtTime(0.0001, start + length);\n  oscillator.connect(envelope).connect(bus);\n  oscillator.start(start);\n  oscillator.stop(start + length);\n  return oscillator;\n}\n\nasync function playPhrases(indices) {\n  stopAudio(\"Playback stopped.\");\n  const contextConstructor = globalThis.AudioContext ?? globalThis.webkitAudioContext;\n  if (!contextConstructor) {\n    audioStatus.textContent = \"Audio is unavailable in this browser.\";\n    return;\n  }\n  try {\n    audio ??= new contextConstructor();\n    const current = { voices: [], timers: [], bus: audio.createGain() };\n    playback = current;\n    stop.disabled = false;\n    await audio.resume();\n    if (playback !== current) return;\n    current.bus.connect(audio.destination);\n    const beat = 60 / Number(tempo.value);\n    const origin = audio.currentTime + 0.03;\n    let index = 0;\n    for (const phraseIndex of indices) {\n      const [, count, thumb, pinky] = score[phraseIndex];\n      current.timers.push(setTimeout(() => {\n        rows.forEach((row, i) => row.classList.toggle(\"current-phrase\", i === phraseIndex));\n        audioStatus.textContent = \"Playing phrase \" + (phraseIndex + 1) + \" · \" + count + \" pulses.\";\n      }, 1000 * beat * index));\n      for (let i = 0; i < count; i++) {\n        const start = origin + beat * index++;\n        for (const note of [thumb, pinky]) current.voices.push(pulse(note, start, beat * 0.54, current.bus));\n      }\n    }\n    current.timers.push(setTimeout(() => stopAudio(\"Playback complete.\"), 1000 * (beat * index + 0.03)));\n  } catch {\n    stopAudio(\"Playback unavailable.\");\n    audioStatus.textContent = \"Playback unavailable.\";\n  }\n}\n\ntempo.addEventListener(\"input\", () => { byId(\"tempo-label\").textContent = tempo.value + \" BPM\"; });\nplay.addEventListener(\"click\", () => playPhrases(score.map((_, i) => i)));\nstop.addEventListener(\"click\", () => stopAudio(\"Playback stopped.\"));\nfor (const button of document.querySelectorAll(\"[data-phrase]\")) {\n  button.addEventListener(\"click\", () => playPhrases([Number(button.dataset.phrase)]));\n}\n\nlet movement = -1;\nlet movementTimer;\nconst movementEls = [...document.querySelectorAll(\"[data-movement]\")];\nconst movementPlay = byId(\"run-motion\");\nfunction showMovement() {\n  movementEls.forEach((el, i) => el.classList.toggle(\"active-motion\", movement === i));\n  byId(\"motion-status\").textContent =\n    movement < 0 ? \"17 movements\" : (movement + 1) + \" / 17 · \" + heartbeat[movement];\n}\nfunction stopMovement() {\n  clearInterval(movementTimer);\n  movementTimer = undefined;\n  movementPlay.textContent = \"Play movements\";\n}\nbyId(\"advance-motion\").addEventListener(\"click\", () => {\n  stopMovement();\n  movement = (movement + 1) % heartbeat.length;\n  showMovement();\n});\nbyId(\"reset-motion\").addEventListener(\"click\", () => {\n  stopMovement();\n  movement = -1;\n  showMovement();\n});\nmovementPlay.addEventListener(\"click\", () => {\n  if (movementTimer) {\n    stopMovement();\n    return;\n  }\n  movement = 0;\n  showMovement();\n  movementPlay.textContent = \"Pause movements\";\n  movementTimer = setInterval(() => {\n    if (movement + 1 === heartbeat.length) return stopMovement();\n    movement++;\n    showMovement();\n  }, 420);\n});\n\nconst scaleInput = byId(\"scale-input\");\nconst scaleResult = byId(\"scale-result\");\nconst scaleFormat = new Intl.NumberFormat(\"en\", {minimumFractionDigits:4, maximumFractionDigits:4});\n\nfunction updateScale() {\n  try {\n    if (!scaleInput.value.trim()) throw new RangeError(\"Enter an input.\");\n    scaleResult.textContent = scaleFormat.format(scaleValue(Number(scaleInput.value)));\n  } catch (error) {\n    scaleResult.textContent = error.message;\n  }\n}\nscaleInput.addEventListener(\"input\", updateScale);\nfor (const button of document.querySelectorAll(\"[data-scale]\")) {\n  button.addEventListener(\"click\", () => { scaleInput.value = button.dataset.scale; updateScale(); });\n}\n\nconst search = byId(\"archive-search\");\nconst branch = byId(\"archive-branch\");\nconst records = [...document.querySelectorAll(\"[data-record]\")];\nfunction filterRecords() {\n  const query = search.value.trim().toLowerCase();\n  let count = 0;\n  for (const row of records) {\n    row.hidden = Boolean(branch.value && branch.value !== row.dataset.branch) ||\n      !row.textContent.toLowerCase().includes(query);\n    if (!row.hidden) count++;\n  }\n  byId(\"record-count\").textContent = count + (count === 1 ? \" record\" : \" records\");\n  byId(\"no-records\").hidden = count > 0;\n}\nsearch.addEventListener(\"input\", filterRecords);\nbranch.addEventListener(\"change\", filterRecords);\n","model.mjs":"export const referenceYear = 2024;\nexport const minYear = -10000;\nexport const maxYear = 10000;\n\nconst phases = (year, period) => ((year - referenceYear) % period + period) % period;\n\nexport function cycleAt(year) {\n  if (!Number.isSafeInteger(year) || year < minYear || year > maxYear) {\n    throw new RangeError(\"Enter a whole year from −10000 to 10000.\");\n  }\n  const broods = [\n    { name: \"Brood XIX\", cycleYears: 13 },\n    { name: \"Brood XIII\", cycleYears: 17 }\n  ].map(brood => {\n    const phase = phases(year, brood.cycleYears);\n    const lastYear = year - phase;\n    return { ...brood, phase, scheduled: phase === 0, lastYear, nextYear: lastYear + brood.cycleYears };\n  });\n  const phase221 = phases(year, 221);\n  return {\n    year, broods, recurrenceYears: 221, shared: phase221 === 0,\n    sharedAtOrBefore: year - phase221,\n    nextSharedYear: year - phase221 + 221\n  };\n}\n\nexport const score = [\n  [\"May I remind you how smart Americans used to be\", 10, \"F♯\", \"C♯\"],\n  [\"They could take ashes out of their fireplace\", 8, \"G♯\", \"D♯\"],\n  [\"Put it in a bed warmer\", 6, \"A♯\", \"F♯\"],\n  [\"Put it between their mattresses\", 5, \"C♯\", \"G♯\"],\n  [\"And not burn themselves\", 4, \"D♯\", \"A♯\"],\n  [\"Some of them even had candles on their Christmas trees\", 10, \"F♯\", \"C♯\"],\n  [\"So if you think we’re smart today, we ain’t\", 9, \"G♯\", \"D♯\"],\n  [\"Just sayin’\", 2, \"A♯\", \"F♯\"]\n];\n\nexport const pulseCount = score.reduce((total, phrase) => total + phrase[1], 0);\nexport const heartbeatQuote = \"up down up down left right left right left right left left. Left right left left left.\";\nexport const heartbeat = heartbeatQuote.toLowerCase().match(/\\b(?:up|down|left|right)\\b/g);\nexport const pitchMultiplier = Math.PI * 1.618 * 1;\nexport const frequencyPresets = [423, 202.8, 10, 13, 7.83, 110];\n\nexport function scaleValue(input) {\n  if (!Number.isFinite(input) || input < 0 || input > 1e9) {\n    throw new RangeError(\"Enter a number from 0 to 1,000,000,000.\");\n  }\n  return input * pitchMultiplier;\n}\n","history.css":".history-page [hidden] { display: none; }\n.history-hero {\n  padding: clamp(34px, 6vw, 80px) 0 24px;\n}\n.history-hero h1 {\n  max-width: 17ch;\n  font-size: clamp(2.65rem, 7.2vw, 6.25rem);\n  text-wrap: balance;\n}\n.history-hero .hero-copy { max-width: 58ch; }\n.era-index {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n  padding: 24px 0 0;\n  margin-top: 28px;\n  border-top: 1px solid var(--line);\n}\n.era-index a {\n  display: inline-block;\n  padding: 5px 11px;\n  border: 1px solid var(--line);\n  border-radius: 20px;\n  font-size: .87rem;\n  text-decoration: none;\n}\n.era-index a:hover { background: var(--accent); }\n.history-tools {\n  display: grid;\n  grid-template-columns: minmax(9rem, 2fr) minmax(8rem, 1.2fr) minmax(8rem, 1.2fr) auto;\n  gap: 12px;\n  align-items: end;\n}\n.history-tools label, .lab-controls label {\n  display: grid;\n  gap: 4px;\n  min-width: 0;\n  font-size: .88rem;\n  font-weight: 650;\n}\n.history-tools button { min-height: 39px; }\n.history-group {\n  margin-top: 23px;\n  scroll-margin-top: 16px;\n}\n.history-group h3 {\n  padding: 10px 14px;\n  background: var(--accent);\n  border-radius: 6px;\n  font-size: 1.32rem;\n}\n.history-records {\n  margin: 0;\n  padding: 0;\n  list-style: none;\n}\n.history-records li {\n  display: grid;\n  grid-template-columns: minmax(120px, 25%) minmax(0, 1fr);\n  gap: 16px;\n  padding: 16px 14px;\n  border-bottom: 1px solid var(--line);\n  scroll-margin-top: 12px;\n}\n.history-records li:target { background: var(--gold); }\n.history-records h4 { margin: 0; font-size: 1.12rem; }\n.history-records h4 a { color: inherit; text-decoration: none; }\n.history-records h4 a:hover { text-decoration: underline; }\n.history-records p { margin: 6px 0 0; }\n.history-date { color: var(--forest); font-size: .88rem; }\n.history-date span { display: block; margin-top: 4px; color: var(--muted); }\n.history-region { color: var(--muted); font-size: .87rem; }\n.history-labs {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 14px;\n  align-items: start;\n}\n.history-labs .panel + .panel { margin-top: 0; }\n.lab-controls { display: grid; gap: 12px; }\n.lab-controls select { width: 100%; }\n.pattern-grid {\n  display: grid;\n  grid-auto-flow: column;\n  grid-auto-columns: minmax(0, 1fr);\n  gap: 4px;\n}\n.pattern-grid span {\n  text-align: center;\n  padding: 5px 1px;\n  border: 1px solid var(--line);\n  border-radius: 4px;\n}\n.pattern-grid .strong-beat { background: var(--forest); color: white; }\n.pattern-grid .beat { background: var(--accent); }\n.period-result {\n  display: block;\n  margin-top: 14px;\n  padding: 10px 12px;\n  border-radius: 6px;\n  background: var(--accent);\n  font-variant-numeric: tabular-nums;\n}\n@media (max-width: 700px) {\n  .history-tools { grid-template-columns: repeat(2, minmax(0, 1fr)); }\n  .history-tools label:first-child { grid-column: 1 / -1; }\n  .history-tools button { justify-self: start; }\n  .history-labs { grid-template-columns: 1fr; }\n}\n@media (max-width: 480px) {\n  .history-records li { grid-template-columns: 1fr; gap: 6px; padding-inline: 8px; }\n  .history-date span { display: inline; margin-left: 6px; }\n}\n","history-client.mjs":"import { patterns, periods, periodRatio } from \"./history-lab.mjs\";\n\nconst byId = id => document.getElementById(id);\nconst normalize = value => value.normalize(\"NFD\").replace(/\\p{M}/gu, \"\").toLowerCase();\nconst search = byId(\"history-search\");\nconst era = byId(\"history-era\");\nconst domain = byId(\"history-domain\");\nconst groups = Array.from(document.querySelectorAll(\"[data-era-group]\"), group => ({\n  group,\n  entries: Array.from(group.querySelectorAll(\"[data-history-record]\"), entry => ({ entry, terms: normalize(entry.textContent) }))\n}));\n\nfunction filter() {\n  const terms = normalize(search.value).trim().split(/\\s+/).filter(Boolean);\n  let count = 0;\n  for (const { group, entries } of groups) {\n    let visible = 0;\n    for (const { entry, terms: text } of entries) {\n      const matches = (!era.value || entry.dataset.era === era.value)\n        && (!domain.value || entry.dataset.domain === domain.value)\n        && terms.every(term => text.includes(term));\n      entry.hidden = !matches;\n      visible += Number(matches);\n    }\n    group.hidden = visible === 0;\n    count += visible;\n  }\n  byId(\"history-count\").textContent = count ? `${count} ${count === 1 ? \"entry\" : \"entries\"}` : \"No matching entries.\";\n}\n\nsearch.addEventListener(\"input\", filter);\nera.addEventListener(\"change\", filter);\ndomain.addEventListener(\"change\", filter);\nfunction clearFilters() {\n  search.value = \"\";\n  era.value = \"\";\n  domain.value = \"\";\n  filter();\n}\nbyId(\"history-clear\").addEventListener(\"click\", clearFilters);\ndocument.querySelector(\".era-index\").addEventListener(\"click\", clearFilters);\nfilter();\n\nconst patternInput = byId(\"pattern\");\nconst tempo = byId(\"pattern-tempo\");\nconst grid = byId(\"pattern-grid\");\nconst play = byId(\"pattern-play\");\nconst stop = byId(\"pattern-stop\");\nconst status = byId(\"pattern-status\");\nconst getPattern = () => patterns.find(p => p.id === patternInput.value);\nlet audio;\nlet pulseSources = [];\nlet finish;\nlet playback = 0;\n\nfunction stopPattern(message) {\n  playback += 1;\n  clearTimeout(finish);\n  for (const oscillator of pulseSources) oscillator.stop();\n  pulseSources = [];\n  play.disabled = false;\n  stop.disabled = true;\n  status.textContent = message;\n}\n\nfunction drawPattern() {\n  const { steps, overlay } = getPattern();\n  grid.replaceChildren();\n  for (const [i, accent] of steps.entries()) {\n    const mark = document.createElement(\"span\");\n    mark.className = accent === 2 ? \"strong-beat\" : accent === 1 ? \"beat\" : \"rest\";\n    mark.textContent = accent === 2 ? \"●\" : accent === 1 ? \"•\" : \"–\";\n    if (overlay?.[i]) mark.textContent += \" +\";\n    mark.setAttribute(\"aria-label\", `Pulse ${i + 1}, ${accent === 2 ? \"accent\" : accent === 1 ? \"beat\" : \"upper part rests\"}${overlay?.[i] ? \", lower part beat\" : \"\"}`);\n    grid.append(mark);\n  }\n}\n\nfunction clickAt(time, frequency, volume) {\n  const oscillator = audio.createOscillator();\n  const gain = audio.createGain();\n  oscillator.frequency.value = frequency;\n  gain.gain.setValueAtTime(volume, time);\n  gain.gain.exponentialRampToValueAtTime(0.001, time + 0.07);\n  oscillator.connect(gain).connect(audio.destination);\n  oscillator.start(time);\n  oscillator.stop(time + 0.075);\n  pulseSources.push(oscillator);\n}\n\nplay.addEventListener(\"click\", async () => {\n  const run = ++playback;\n  play.disabled = true;\n  stop.disabled = false;\n  try {\n    audio ??= new (window.AudioContext || window.webkitAudioContext)();\n    await audio.resume();\n    if (run !== playback) return;\n    const { steps, overlay, beats } = getPattern();\n    const stepSeconds = 60 / Number(tempo.value) * beats / steps.length;\n    const start = audio.currentTime + 0.04;\n    for (let i = 0; i < steps.length * 2; i += 1) {\n      const index = i % steps.length;\n      const at = start + stepSeconds * i;\n      if (steps[index]) clickAt(at, steps[index] === 2 ? 880 : 620, 0.16);\n      if (overlay?.[index]) clickAt(at, 330, 0.14);\n    }\n    status.textContent = \"Playing two cycles.\";\n    finish = setTimeout(() => stopPattern(\"Playback finished.\"), (2 * steps.length * stepSeconds + 0.12) * 1000);\n  } catch {\n    if (run === playback) stopPattern(\"Audio playback is unavailable in this browser.\");\n  }\n});\nstop.addEventListener(\"click\", () => stopPattern(\"Playback stopped.\"));\npatternInput.addEventListener(\"change\", () => {\n  stopPattern(\"Audio starts when you press Play.\");\n  drawPattern();\n});\ntempo.addEventListener(\"input\", () => { byId(\"pattern-bpm\").textContent = tempo.value + \" BPM\"; });\ndrawPattern();\n\nconst periodValues = new Map(periods.map(([key, , seconds]) => [key, seconds]));\nconst first = byId(\"period-first\");\nconst second = byId(\"period-second\");\nconst number = new Intl.NumberFormat(\"en\", { maximumSignificantDigits: 5 });\nconst format = value => value < 0.001 || value >= 1e9 ? value.toExponential(3) : number.format(value);\nfunction compare() {\n  const a = periodValues.get(first.value);\n  const b = periodValues.get(second.value);\n  byId(\"period-output\").textContent = `First ≈ ${format(a)} s. Second ≈ ${format(b)} s. Second ÷ first ≈ ${format(periodRatio(a, b))}.`;\n}\nfirst.addEventListener(\"change\", compare);\nsecond.addEventListener(\"change\", compare);\ncompare();\n\ndocument.querySelectorAll(\".history-tools, .lab-controls\").forEach(node => { node.hidden = false; });\n","history-lab.mjs":"export const patterns = [\n  { id: \"duple\", label: \"2/4 · Duple meter\", steps: [2, 1], beats: 2 },\n  { id: \"triple\", label: \"3/4 · Triple meter\", steps: [2, 1, 1], beats: 3 },\n  { id: \"four\", label: \"4/4 · Four-beat meter\", steps: [2, 1, 1, 1], beats: 4 },\n  { id: \"compound\", label: \"6/8 · Two beats of three\", steps: [2, 1, 1, 2, 1, 1], beats: 2 },\n  { id: \"aksak\", label: \"Seven pulses · 2 + 2 + 3\", steps: [2, 1, 2, 1, 2, 1, 1], beats: 7 },\n  { id: \"rupak\", label: \"Seven mātrās · 3 + 2 + 2\", steps: [1, 1, 1, 2, 1, 2, 1], beats: 7 },\n  { id: \"cross-rhythm\", label: \"3 against 2 · Six subdivisions\", steps: [2, 0, 0, 2, 0, 0], overlay: [1, 0, 1, 0, 1, 0], beats: 2 }\n];\n\nconst day = 86400;\nconst year = 365.2425 * day;\nexport const periods = [\n  [\"heartbeat\",\"Human heartbeat · 72 BPM example\",60 / 72],\n  [\"demo\",\"Tabor score · 96 BPM demo\",60 / 96],\n  [\"schumann\",\"Schumann resonance · 7.83 Hz reference\",1 / 7.83],\n  [\"tide\",\"Semidiurnal tide · about 12 h 25 min\",12 * 3600 + 25 * 60],\n  [\"circadian\",\"Circadian cycle · 24 h reference\",day],\n  [\"moon\",\"Lunar phases · about 29.53 days\",29.53 * day],\n  [\"sunspots\",\"Sunspot cycle · about 11 years\",11 * year],\n  [\"brood-19\",\"Magi Cicada · 13 years\",13 * year],\n  [\"brood-13\",\"Magi Cicada · 17 years\",17 * year],\n  [\"shared\",\"Magi Cicada · 221-year alignment\",221 * year],\n  [\"precession\",\"Climatic precession · about 23,000 years\",23000 * year]\n];\n\nexport function periodRatio(first, second) {\n  return second / first;\n}\n"};
